const fs=require('fs');
const p='/Users/juliusolsson/.config/agent-code/workspace.json';
const data=JSON.parse(fs.readFileSync(p,'utf8')).workspace;
const sessions=data.sessions||{};
function leaves(n,out=[]){ if(!n)return out; if(n.type==='leaf') out.push(n.sessionId); else {leaves(n.a,out); leaves(n.b,out)} return out; }
const grid=new Map();
for(const tab of data.tabs||[]) for(const id of leaves(tab.root)) grid.set(id,{surface:'grid',tabId:tab.id,tabTitle:tab.title});
const detached=new Map(Object.values(data.detachedSessions||{}).map(e=>[e.sessionId,e]));
const buried=new Map((data.buried||[]).map(e=>[e.sessionId,e]));
const tiled=[];
(data.dispatchMode?.tiled?.lanes||[]).forEach((lane,i)=>{ if(lane.selectedSessionId) tiled.push([i,lane.selectedSessionId]); });
const groups=new Map();
for(const [id,meta] of Object.entries(sessions)){
  if(meta.providerSessionId){
    const arr=groups.get(meta.providerSessionId)||[];
    let surface='unowned'; let owner='';
    if(grid.has(id)){ surface='grid'; owner=grid.get(id).tabTitle; }
    else if(detached.has(id)){ surface='detached'; owner=detached.get(id).projectTabTitle; }
    else if(buried.has(id)){ surface='buried'; owner=buried.get(id).sourceTabTitle; }
    const laneIndexes=tiled.filter(([,sid])=>sid===id).map(([i])=>i);
    arr.push({id, kind:meta.kind||'claude', cwd:meta.cwd, surface, owner, title:meta.title||'', laneIndexes, linkedParentId:meta.linkedParentId, orchestrationParentId:meta.orchestrationParentId, inheritedParentProviderSessionId:meta.inheritedParentProviderSessionId, inheritedProviderSessionId:meta.inheritedProviderSessionId});
    groups.set(meta.providerSessionId,arr);
  }
}
const dup=[...groups.entries()].filter(([,arr])=>arr.length>1).sort((a,b)=>b[1].length-a[1].length || a[0].localeCompare(b[0]));
const missing=Object.entries(sessions).filter(([,m])=>(m.kind||'claude')!=='terminal' && !m.providerSessionId);
const owned=new Set([...grid.keys(),...detached.keys(),...buried.keys()]);
const unowned=Object.keys(sessions).filter(id=>!owned.has(id));
console.log(JSON.stringify({
  tabs:(data.tabs||[]).length,
  sessions:Object.keys(sessions).length,
  grid:grid.size,
  detached:detached.size,
  buried:buried.size,
  tiledLanes:tiled,
  providerIds:groups.size,
  duplicateProviderGroups:dup.length,
  duplicateProviderSessions:dup.reduce((n,[,a])=>n+a.length,0),
  missingProviderAgentRecords:missing.length,
  unownedSessions:unowned.length,
  dup
},null,2));
